ValidationRule.errorConditionFormula:
IF( AND(
ISCHANGED(ReactiveLicense__c), ReactiveLicense__c= true, NOT(ISPICKVAL(Status__c, "C - Current, Valid & In Good Standing")), NOT(ISPICKVAL(Status__c, "CM - Current, Valid & In Good Standing/Maint. Requirement Due")), NOT(ISPICKVAL(Status__c, "CR - Current/Next Renewal Paid")), NOT(ISPICKVAL(Status__c, "R - Valid Thru Expiration Date, Subject To Renewal")), NOT(ISPICKVAL(Status__c, "RM - Valid Thru Exp Date, Subject To Renwl/Maint Reqmt Due")), NOT(ISPICKVAL(Status__c, " Z - Current & Valid, But Subject To Disciplinary Requirement")), NOT(ISPICKVAL(Status__c, "Z1 - Susp Due To 1)Loss Of Bond By Licensee And/Or Dependent Or")), NOT(ISPICKVAL(Status__c, "ZI - Automatically Forfeited Due To Insurance Loss"))
), true, false )
